previewCss:
.darma-loader-darma-b15-rowing-oars { --accent: var(--loader-color, #0369a1); --accent-2: var(--loader-secondary-color, #7dd3fc); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .62); position: relative; }
.darma-loader-darma-b15-rowing-oars .darma-loader-darma-b15-rowing-oars__hull { position: absolute; left: 16%; top: 42%; width: 68%; height: 18%; border-radius: 46% 8% 8% 46% / 60% 40% 40% 60%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b15-rowing-oars-row-glide calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b15-rowing-oars .darma-loader-darma-b15-rowing-oars__oar { position: absolute; left: 48%; top: 45%; width: 42%; height: 5%; border-radius: 3px; background: linear-gradient(90deg, #cbd5e1, #64748b); transform-origin: 3% 50%; }
.darma-loader-darma-b15-rowing-oars .darma-loader-darma-b15-rowing-oars__oar::after { content: ''; position: absolute; left: 82%; top: -70%; width: 22%; height: 240%; border-radius: 40%; background: var(--accent); }
.darma-loader-darma-b15-rowing-oars .darma-loader-darma-b15-rowing-oars__oar:nth-of-type(1) { animation: darma-loader-darma-b15-rowing-oars-row-stroke calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b15-rowing-oars .darma-loader-darma-b15-rowing-oars__oar:nth-of-type(2) { animation: darma-loader-darma-b15-rowing-oars-row-stroke-mirror calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b15-rowing-oars .darma-loader-darma-b15-rowing-oars__wave { position: absolute; left: 2%; right: 2%; bottom: 12%; height: 8%; border-radius: 4px; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent) 45%, transparent) 0 14%, transparent 0 28%); animation: darma-loader-darma-b15-rowing-oars-row-water calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
@keyframes darma-loader-darma-b15-rowing-oars-row-stroke { 0%, 100% { transform: rotate(-36deg); } 50% { transform: rotate(-4deg); } }
@keyframes darma-loader-darma-b15-rowing-oars-row-stroke-mirror { 0%, 100% { transform: rotate(36deg); } 50% { transform: rotate(4deg); } }
@keyframes darma-loader-darma-b15-rowing-oars-row-glide { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(-5%); } }
@keyframes darma-loader-darma-b15-rowing-oars-row-water { to { background-position: -28% 0; } }

